// Wyciąga JSON z odpowiedzi modelu i składa body dla Kluska API.
const cfg = $('Prompty').first().json;
const raw = $input.first().json.choices?.[0]?.message?.content;
if (!raw || typeof raw !== 'string') {
  throw new Error('OpenRouter nie zwrócił treści: ' + JSON.stringify($input.first().json).slice(0, 500));
}

// Model czasem mimo zakazu owija JSON w ```json ... ``` albo dopisuje komentarz.
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start === -1 || end <= start) {
  throw new Error('Brak obiektu JSON w odpowiedzi modelu: ' + raw.slice(0, 500));
}
let post;
try {
  post = JSON.parse(raw.slice(start, end + 1));
} catch (e) {
  throw new Error('Niepoprawny JSON od modelu (' + e.message + '): ' + raw.slice(0, 500));
}

if (!post.title || !post.content) {
  throw new Error('Model nie zwrócił title/content');
}

const allowed = ['Trening', 'Dieta i Suplementacja', 'Regeneracja', 'Motywacja'];
const cat = String(post.category || '');
const category = allowed.find((c) => c === cat.trim()) || allowed.find((c) => cat.includes(c)) || 'Trening';

// Modele często zmyślają ID zdjęć z Unsplash — sprawdzamy, czy URL faktycznie działa.
let coverImageUrl = typeof post.coverImageUrl === 'string' ? post.coverImageUrl.trim() : '';
if (!coverImageUrl.startsWith('https://images.unsplash.com/')) {
  coverImageUrl = '';
} else if (this.helpers?.httpRequest) {
  try {
    await this.helpers.httpRequest({ method: 'HEAD', url: coverImageUrl, timeout: 10000 });
  } catch (e) {
    coverImageUrl = '';
  }
}

const body = {
  userId: cfg.userId, // zawsze z konfiguracji, nie z odpowiedzi modelu
  title: String(post.title).trim(),
  content: String(post.content).trim(),
  category,
  status: 'published',
};
if (coverImageUrl) body.coverImageUrl = coverImageUrl;

return [{ json: { body, kluskaApiKey: cfg.kluskaApiKey } }];
